add_action( 'woocommerce_after_shop_loop_item_title', 'perfectpixel_custom_field_in_loop', 4 );

function perfectpixel_custom_field_in_loop() {
	$value = get_post_meta( get_the_ID(), sanitize_key( '{{loop_field_key}}' ), true );
	if ( is_array( $value ) ) {
		$value = implode( ', ', array_map( 'strval', array_filter( $value, 'is_scalar' ) ) );
	}
	if ( '' === trim( (string) $value ) ) {
		return;
	}
	$label = trim( '{{loop_field_label}}' );
	echo '<div class="perfectpixel-loop-field" style="font-size:.85em;margin:.25em 0">' . ( '' !== $label ? esc_html( $label ) . ' ' : '' ) . esc_html( $value ) . '</div>';
}
